insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$sao-goncalo$q$, $q$https://do.saogoncalo.rj.gov.br/diario/2010_07_13.pdf (Res. 084/SEMTRAN/2010) ; https://do.saogoncalo.rj.gov.br/diario/2014_11_28.pdf (Res. 093/SEMTRAN/2014) ; https://do.saogoncalo.rj.gov.br/diario/2025_04_17.pdf (Res. 44/SEMMATRAN/2025) ; https://do.saogoncalo.rj.gov.br/diario/2024_01_31.pdf (Res. 19/SEMTRAN/2024)$q$, $q$Atos oficiais de São Gonçalo: domínio público (Lei 9.610/1998 art. 8º IV). Geometria das vias: OpenStreetMap (ODbL 1.0, © colaboradores do OSM), casada por nome e trecho.$q$, 22, $q$Três resoluções de trânsito vigentes, sem revogação achada no DO até 10/2026 (pesquisa de 10/10/2026, verificação de 11/10/2026). Não há zona central nem horário geral de caminhões. Carga e descarga (pontos com horário; rotativo > 3,5 t só nos horários sinalizados, Dec. 374/2022, art. 12, §2º) é operação e fica fora da camada.$q$);
